def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r,c)]
        visited[r][c] = True
        while stack:
            i,j = stack.pop()
            for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni,nj = i+di, j+dj
                if 0<=ni<rows and 0<=nj<cols and not visited[ni][nj] and grid[ni][nj]==1:
                    visited[ni][nj] = True
                    stack.append((ni,nj))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                dfs(i,j)
                count+=1
    return count

