def solve(intervals):
    """Merge overlapping or touching intervals.
    Handles malformed input gracefully: ignores intervals that are not
    length‑2 sequences of comparable numbers.
    Returns a new list of intervals sorted by start.
    """
    if not intervals:
        return []
    # Filter and copy intervals to avoid mutating input
    clean = []
    for iv in intervals:
        try:
            s, e = iv[0], iv[1]
        except Exception:
            continue
        # Ensure comparable (int/float)
        try:
            if s <= e:
                clean.append([s, e])
            else:
                # If start > end, swap to make valid
                clean.append([e, s])
        except Exception:
            continue
    if not clean:
        return []
    # Sort by start then end
    clean.sort(key=lambda x: (x[0], x[1]))
    merged = [clean[0][:]]
    for s, e in clean[1:]:
        last = merged[-1]
        if s <= last[1]:  # overlap or touch
            last[1] = max(last[1], e)
        else:
            merged.append([s, e])
    return merged

