def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: iterable of strings or ints representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero. If division by zero occurs, treat the result as 0.
    Returns the integer result; empty input returns 0.
    """
    if not tokens:
        return 0
    stack = []
    for tok in tokens:
        op = str(tok)
        if op in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if op == '+':
                res = a + b
            elif op == '-':
                res = a - b
            elif op == '*':
                res = a * b
            else:  # division
                if b == 0:
                    res = 0
                else:
                    # Truncate toward zero
                    res = int(a / b)
            stack.append(res)
        else:
            try:
                stack.append(int(tok))
            except Exception:
                stack.append(0)
    return stack[-1] if stack else 0

