import bisect
def solve(nums):
    """Return length of longest strictly increasing subsequence using O(n log n)."""
    tails = []
    for x in nums:
        # find insertion point
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
